def transform(g):
    h,w=len(g),len(g[0]); out=[r[:] for r in g]
    ones=[(i,j) for i in range(h) for j in range(w) if g[i][j]==1]
    for a in range(len(ones)):
        for b in range(a+1,len(ones)):
            (r1,c1),(r2,c2)=ones[a],ones[b]
            if abs(r2-r1)!=abs(c2-c1) or (r1,c1)==(r2,c2): continue
            dr=(r2>r1)-(r2<r1); dc=(c2>c1)-(c2<c1)
            anti=(r1+c1)==(r2+c2)
            seg=set(); r,c=r1,c1
            while (r,c)!=(r2,c2):
                seg.add((r,c)); r+=dr; c+=dc
            for (i,j) in seg:
                if out[i][j]!=6: out[i][j]=1
            for i in range(h):
                for j in range(w):
                    if g[i][j]==6 and (i,j) in seg:
                        if anti:
                            d=i-j
                            for k in range(h):
                                jj=k-d
                                if 0<=jj<w: out[k][jj]=6
                        else:
                            s=i+j
                            for k in range(h):
                                jj=s-k
                                if 0<=jj<w: out[k][jj]=6
    return out
